public sealed record FeeBand(decimal Floor, decimal? Ceiling, decimal AnnualRate);

public static class AcmeTier2026
{
    public const string ScheduleCode = "ACME-TIER-2026";
    public const decimal AnnualMinimum = 2_500m;

    public static readonly IReadOnlyList<FeeBand> Bands = new[]
    {
        new FeeBand(0m, 1_000_000m, 0.0100m),
        new FeeBand(1_000_000m, 3_000_000m, 0.0080m),
        new FeeBand(3_000_000m, 8_000_000m, 0.0060m),
        new FeeBand(8_000_000m, null, 0.0045m),
    };
}

export function renderInvoice(inv: HouseholdInvoice): string {
  const header = [
    "Contoso Advisors",
    `Invoice ${invoiceLabel(inv)} - ${inv.householdName}`,
    `Schedule ${inv.scheduleCode}, period ${inv.periodStart} to ${inv.periodEnd} (billed in advance)`,
  ];
  const body = inv.lines.map(formatLine);
  const alloc = Object.entries(inv.allocations)
    .filter(([, amt]) => amt > 0)
    .map(([acct, amt]) => `  ${acct}: ${usd.format(amt)}`);
  return [...header, "", ...body, "", `Total: ${usd.format(invoiceTotal(inv))}`, "Debited from:", ...alloc].join("\n");
}

public static decimal AnnualTieredFee(decimal aum, IReadOnlyList<FeeTier> tiers)
    {
        decimal total = 0m;
        foreach (var tier in tiers.OrderBy(t => t.LowerBound))
        {
            if (aum <= tier.LowerBound) break;
            var top = tier.UpperBound is { } ub ? Math.Min(aum, ub) : aum;
            total += (top - tier.LowerBound) * tier.AnnualRate;
        }
        return total;
    }
